<script setup lang="ts">import {ref,onMounted,computed,watch} from 'vue';import {useRoute} from 'vue-router';import {useLab} from '../stores/laboratory';import {calibrate,getVersions} from '../api/runs';import {useTask} from '../hooks/useTask';import {usePolling} from '../hooks/usePolling';import PageTitle from '../components/common/PageTitle.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';import StatusBadge from '../components/common/StatusBadge.vue';import EmptyState from '../components/common/EmptyState.vue';import MethodSummary from '../components/MethodSummary.vue';import AgreementPlot from '../components/AgreementPlot.vue';import {number,date} from '../utils/format';import {versionStatuses} from '../constants/enums';import type {RunVersion} from '../types/domain';
const lab=useLab(),route=useRoute(),selected=ref(Number(route.query.run)||0),versionId=ref<number|null>(null),versions=ref<RunVersion[]>([]),value=ref(50),estimate=ref<number>(),{error,perform}=useTask();
const run=computed(()=>lab.runs.find(r=>r.id===selected.value));
const shown=computed<Partial<RunVersion>|undefined>(()=>versions.value.find(v=>v.id===versionId.value)||versions.value.find(v=>v.id===run.value?.active_version_id)||versions.value[0]||(run.value?{id:run.value.active_version_id||undefined,version_no:run.value.active_version_no||1,source:'original',status:'active',config:run.value.result.config,result:run.value.result,error:''}:undefined));
const isActive=computed(()=>!!shown.value&&shown.value.id===run.value?.active_version_id);
const loadVersions=async()=>{versions.value=run.value?await getVersions(selected.value):[];if(!versions.value.find(v=>v.id===versionId.value))versionId.value=run.value?.active_version_id||versions.value[0]?.id||null;};
onMounted(()=>perform(async()=>{await lab.load();if(!selected.value)selected.value=lab.runs[0]?.id||0;await loadVersions();}));
watch(()=>route.query.run,v=>{if(v){selected.value=Number(v);versionId.value=null;perform(loadVersions);}});
watch(selected,()=>{versionId.value=null;estimate.value=undefined;perform(loadVersions);});
watch(versionId,()=>{estimate.value=undefined;});
usePolling(async()=>{if(run.value&&['queued','running'].includes(run.value.status)){await lab.load();await loadVersions();}else if(lab.runs.some(r=>r.pending_batch_id))await lab.load();});
function inverse(){estimate.value=undefined;perform(async()=>{const r=await calibrate(selected.value,value.value,shown.value?.id??null);estimate.value=r.reference_estimate;});}
</script>
<template><PageTitle index="04" title="从拟合关系，读到测量边界" text="每次试算都标明所用版本；启用中的结果与归档版本可分别核对。"><RouterLink class="outline" :to="'/qualifications?run='+selected">记录资格用途 ↗</RouterLink></PageTitle>
<ErrorNotice :message="error" @retry="perform(lab.load)"/>
<div class="run-selector"><label>研究档案<select v-model="selected"><option v-for="r in lab.runs" :key="r.id" :value="r.id">#{{r.id}} {{r.name}}<template v-if="r.active_version_no&&r.active_version_no>1"> · v{{r.active_version_no}}</template></option></select></label><StatusBadge v-if="run" :status="run.status"/></div>
<template v-if="run?.status==='completed'&&shown?.result?.fingerprint">
  <div class="version-strip"><label>查看版本<select v-model="versionId"><option v-for="v in versions" :key="v.id" :value="v.id">v{{v.version_no}} · {{versionStatuses[v.status]||v.status}} · λ={{v.config?.lambda_ratio}}<template v-if="v.id===run.active_version_id">（当前启用）</template></option></select></label><p class="input-note">本视图完整引用该版参数：数据集 #{{shown.config?.dataset_id}}、X {{number(shown.config?.range_low,2)}}—{{number(shown.config?.range_high,2)}}%、允许误差 ±{{shown.config?.allowance}}、λ={{shown.config?.lambda_ratio}}、Bootstrap {{shown.config?.bootstrap_count}} 次。<template v-if="!isActive">这是归档版本，不影响当前启用的结果。</template><template v-else>当前启用版本。</template></p></div>
  <div class="results-charts"><AgreementPlot :result="shown.result" kind="deming"/><AgreementPlot :result="shown.result" kind="ba"/></div>
  <div class="results-details"><MethodSummary :run="{...run,result:shown.result,allowance:shown.config?.allowance??run.allowance}"/><section class="interval-table"><h2>参数与界限的不确定性</h2><table><thead><tr><th>估计量</th><th>点估计</th><th>95% bootstrap CI</th></tr></thead><tbody><tr v-for="row in [['截距',shown.result.intercept,shown.result.intercept_ci],['斜率',shown.result.slope,shown.result.slope_ci],['平均偏差',shown.result.bias,shown.result.bias_ci],['一致性下界',shown.result.loa_lower,shown.result.lower_ci],['一致性上界',shown.result.loa_upper,shown.result.upper_ci]]" :key="String(row[0])"><td>{{row[0]}}</td><td>{{number(row[1] as number,4)}}</td><td>{{(row[2] as number[])?.map(v=>number(v,4)).join(' — ')}}</td></tr></tbody></table><p class="input-note">成功重采样 {{shown.result.bootstrap_success}} 次 / 退化 {{shown.result.bootstrap_failed}} 次 / seed {{shown.result.bootstrap_seed}}。相关系数 r={{number(shown.result.correlation,5)}} 仅描述共同变化。</p></section><form class="calibration-form" @submit.prevent="inverse"><p class="eyebrow">INVERSE CALIBRATION / v{{shown.version_no}}</p><h2>候选读数 → 参考估计</h2><label>候选仪器 Y / %<input v-model.number="value" type="number" min="0" max="100" step=".001" required></label><button class="outline">计算 (Y−a) / b →</button><p v-if="estimate!==undefined" class="inverse-answer" role="status">{{number(estimate,4)}} <small>参考估计 / % · v{{shown.version_no}}</small></p><p class="input-note">v{{shown.version_no}} 的X范围 {{shown.result.x_range?.map(v=>number(v,2)).join('—')}}%；Y范围 {{shown.result.y_range?.map(v=>number(v,2)).join('—')}}%。超出任一范围拒绝外推；点估计不含个体预测误差。</p></form></div>
  <p class="fingerprint">INPUT SHA256 / {{shown.result.fingerprint}}<span v-if="shown.activated_at"> · 启用 {{date(shown.activated_at)}}</span></p>
  <section class="version-directory"><div class="section-heading"><h2>研究版本</h2><span>原结果保留，供资格档案复算</span></div><table><thead><tr><th>版本</th><th>来源</th><th>状态</th><th>λ / 允许误差</th><th>偏差</th><th>指纹</th></tr></thead><tbody><tr v-for="v in versions" :key="v.id" @click="versionId=v.id"><td><b>v{{v.version_no}}</b></td><td>{{v.source==='recalc'?('重算批次 #'+v.batch_id):'原始研究'}}</td><td><span class="status" :class="v.status">{{versionStatuses[v.status]||v.status}}</span></td><td>{{v.config?.lambda_ratio}} / ±{{v.config?.allowance}}</td><td>{{v.result?.bias!==undefined?number(v.result.bias,3):'—'}}</td><td class="fingerprint-cell">{{v.result?.fingerprint?v.result.fingerprint.slice(0,16)+'…':'—'}}</td></tr></tbody></table></section>
</template>
<EmptyState v-else :title="run?.status==='failed'?'研究未完成':'等待配对计算结果'" :text="run?.error||'运行状态会自动刷新。请先建立研究，或从研究目录选择一份已归档记录。'"/></template>
